import hashlib

def _keys(s3,bucket):
    return sorted(x['Key']for page in s3.get_paginator('list_objects_v2').paginate(Bucket=bucket,PaginationConfig={'PageSize':7})for x in page.get('Contents',[]))

def _objects(s3,bucket,keys):
    values={}
    for key in keys:
        response=s3.get_object(Bucket=bucket,Key=key)
        try:data=response['Body'].read()
        finally:response['Body'].close()
        values[key]={'bytes':len(data),'sha256':hashlib.sha256(data).hexdigest(),'metadata':response['Metadata']}
    return values

def remediate(admin,s3,bucket,target,baseline):
    if type(target)is not int or target<1:raise ValueError('positive integer approved shard target required')
    before=admin('bucket','stats','--bucket',bucket)
    if target<before['num_shards']:raise ValueError('shrink requires a separate approved change')
    before_keys=_keys(s3,bucket)
    if before['num_shards']!=target:admin('bucket','reshard','--bucket',bucket,'--num-shards',str(target))
    after=admin('bucket','stats','--bucket',bucket)
    entries={str(i):admin('bi','list','--bucket',bucket,'--shard-id',str(i))for i in range(target)}
    status=admin('reshard','status','--bucket',bucket);after_keys=_keys(s3,bucket)
    latency=baseline['latency']
    diagnosis={'large_omap':'LARGE_OMAP_OBJECTS'in baseline['health'].get('checks',{}),'threshold':baseline['threshold'],'max_index_keys':max(baseline['index_key_counts'].values()),'full_list_max_ns':max(latency['complete_paginated_LIST_ns']),'single_get_max_ns':max(latency['single_full_GET_ns']),'index_is_only_cause_proven':False,'production_performance_certified':False}
    return {'before_stats':before,'after_stats':after,'before_keys':before_keys,'after_keys':after_keys,'shard_entries':entries,'reshard_status':status,'objects_after':_objects(s3,bucket,after_keys),'diagnosis':diagnosis,'production_performance_certified':False}

